36	// CheckAndNotify performs a version check and notifies the user if a newer version is available.
37	// This is the main entry point for the version check system.
38	// The function is silent on all errors to avoid interrupting CLI operations.
39	func CheckAndNotify(ctx context.Context, w io.Writer, currentVersion string) {
40		// Skip checks for dev builds
41		if currentVersion == "dev" || currentVersion == "" {
42			return
43		}
44	
45		// Ensure the global config directory exists
46		if err := ensureGlobalConfigDir(); err != nil {
47			// Silent failure - don't block CLI operations
48			return
49		}
50	
51		// Load the cache to check when we last fetched
52		cache, err := loadCache()
53		if err != nil {
54			cache = &VersionCache{}
55		}
56	
57		// Skip if we checked recently (within 24 hours)
58		if time.Since(cache.LastCheckTime) < checkInterval {
59			return
60		}
61	
62		// Fetch the latest version from the appropriate channel
63		var latestVersion string
64		if isNightly(currentVersion) {
65			latestVersion, err = fetchLatestNightlyVersion(ctx)
66		} else {
67			latestVersion, err = fetchLatestVersion(ctx)
68		}
69	
70		// Always update cache to avoid retrying on every CLI invocation
71		cache.LastCheckTime = time.Now()
72		if saveErr := saveCache(cache); saveErr != nil {
73			logging.Debug(ctx, "version check: failed to save cache",
74				"error", saveErr.Error())
75		}
76	
77		if err != nil {
78			logging.Debug(ctx, "version check: failed to fetch latest version",
79				"error", err.Error())
80			return
81		}
82	
83		// Show notification and offer an interactive upgrade when outdated
84		if isOutdated(currentVersion, latestVersion) {
85			if cache.SkippedVersion == versionCacheKey(latestVersion) {
86				return
87			}
88	
89			action := MaybeAutoUpdate(ctx, w, currentVersion, latestVersion)
90			if action == autoUpdateActionSkipUntilNextVersion {
91				cache.SkippedVersion = versionCacheKey(latestVersion)
92				if saveErr := saveCache(cache); saveErr != nil {
93					logging.Debug(ctx, "version check: failed to save skipped version",
94						"error", saveErr.Error())
95				}
96			}
97		}
98	}
