100	// globalConfigDirPath returns the expanded path to the global config directory (~/.config/entire).
101	func globalConfigDirPath() (string, error) {
102		home, err := os.UserHomeDir()
103		if err != nil {
104			return "", fmt.Errorf("getting home directory: %w", err)
105		}
106		return filepath.Join(home, globalConfigDirName), nil
107	}
