109	// ensureGlobalConfigDir creates the global config directory if it doesn't exist.
110	func ensureGlobalConfigDir() error {
111		configDir, err := globalConfigDirPath()
112		if err != nil {
113			return err
114		}
115	
116		//nolint:gosec // ~/.config/entire is user home directory, 0o755 is appropriate
117		if err := os.MkdirAll(configDir, 0o755); err != nil {
118			return fmt.Errorf("creating config directory: %w", err)
119		}
120	
121		return nil
122	}
