124	// cacheFilePath returns the full path to the version check cache file.
125	func cacheFilePath() (string, error) {
126		configDir, err := globalConfigDirPath()
127		if err != nil {
128			return "", err
129		}
130		return filepath.Join(configDir, cacheFileName), nil
131	}
