133	// loadCache loads the version check cache from disk.
134	// Returns an error if the file doesn't exist or is corrupted.
135	func loadCache() (*VersionCache, error) {
136		filePath, err := cacheFilePath()
137		if err != nil {
138			return nil, err
139		}
140	
141		data, err := os.ReadFile(filePath) //nolint:gosec // cacheFilePath is safe
142		if err != nil {
143			return nil, fmt.Errorf("reading cache file: %w", err)
144		}
145	
146		var cache VersionCache
147		if err := json.Unmarshal(data, &cache); err != nil {
148			return nil, fmt.Errorf("parsing cache: %w", err)
149		}
150	
151		return &cache, nil
152	}
153	
154	// saveCache saves the version check cache to disk.
155	// Uses atomic write semantics (write to temp file, then rename).
156	func saveCache(cache *VersionCache) error {
157		filePath, err := cacheFilePath()
158		if err != nil {
159			return err
160		}
161	
162		// Marshal to JSON
163		data, err := json.MarshalIndent(cache, "", "  ")
164		if err != nil {
165			return fmt.Errorf("marshaling cache: %w", err)
166		}
167	
168		// Write to temp file first (atomic write)
169		dir := filepath.Dir(filePath)
170		tmpFile, err := os.CreateTemp(dir, ".version_check_tmp_")
171		if err != nil {
172			return fmt.Errorf("creating temp file: %w", err)
173		}
174		defer os.Remove(tmpFile.Name())
175	
176		if _, err := tmpFile.Write(data); err != nil {
177			_ = tmpFile.Close() // cleanup on error path
178			return fmt.Errorf("writing cache: %w", err)
179		}
180	
181		if err := tmpFile.Close(); err != nil {
182			return fmt.Errorf("closing temp file: %w", err)
183		}
184	
185		// Rename temp file to final location
186	
187		if err := os.Rename(tmpFile.Name(), filePath); err != nil {
188			return fmt.Errorf("renaming cache file: %w", err)
189		}
190	
191		return nil
192	}
