194	// fetchLatestVersion fetches the latest stable version tag from the GitHub API.
195	func fetchLatestVersion(ctx context.Context) (string, error) {
196		ctx, cancel := context.WithTimeout(ctx, httpTimeout)
197		defer cancel()
198	
199		req, err := http.NewRequestWithContext(ctx, http.MethodGet, githubAPIURL, nil)
200		if err != nil {
201			return "", fmt.Errorf("creating request: %w", err)
202		}
203	
204		req.Header.Set("Accept", "application/vnd.github+json")
205		req.Header.Set("User-Agent", "entire-cli")
206	
207		client := &http.Client{}
208		resp, err := client.Do(req)
209		if err != nil {
210			return "", fmt.Errorf("fetching release info: %w", err)
211		}
212		defer resp.Body.Close()
213	
214		if resp.StatusCode != http.StatusOK {
215			return "", fmt.Errorf("unexpected status code: %d", resp.StatusCode)
216		}
217	
218		body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
219		if err != nil {
220			return "", fmt.Errorf("reading response: %w", err)
221		}
222	
223		version, err := parseGitHubRelease(body)
224		if err != nil {
225			return "", fmt.Errorf("parsing release: %w", err)
226		}
227		return version, nil
228	}
