230	// isNightly returns true if the version string is a nightly build.
231	func isNightly(version string) bool {
232		if !strings.HasPrefix(version, "v") {
233			version = "v" + version
234		}
235		return strings.Contains(semver.Prerelease(version), "nightly")
236	}
237	
238	// fetchLatestNightlyVersion fetches the latest nightly version tag from the GitHub releases list.
239	func fetchLatestNightlyVersion(ctx context.Context) (string, error) {
240		ctx, cancel := context.WithTimeout(ctx, httpTimeout)
241		defer cancel()
242	
243		req, err := http.NewRequestWithContext(ctx, http.MethodGet, githubReleasesURL+"?per_page=20", nil)
244		if err != nil {
245			return "", fmt.Errorf("creating request: %w", err)
246		}
247	
248		req.Header.Set("Accept", "application/vnd.github+json")
249		req.Header.Set("User-Agent", "entire-cli/"+versioninfo.Version)
250	
251		client := &http.Client{}
252		resp, err := client.Do(req)
253		if err != nil {
254			return "", fmt.Errorf("fetching releases: %w", err)
255		}
256		defer resp.Body.Close()
257	
258		if resp.StatusCode != http.StatusOK {
259			return "", fmt.Errorf("unexpected status code: %d", resp.StatusCode)
260		}
261	
262		body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
263		if err != nil {
264			return "", fmt.Errorf("reading response: %w", err)
265		}
266	
267		var releases []GitHubRelease
268		if err := json.Unmarshal(body, &releases); err != nil {
269			return "", fmt.Errorf("parsing JSON: %w", err)
270		}
271	
272		for _, r := range releases {
273			if r.Prerelease && strings.Contains(r.TagName, "-nightly.") {
274				return r.TagName, nil
275			}
276		}
277	
278		return "", errors.New("no nightly release found")
279	}
