281	// parseGitHubRelease parses the GitHub API response and returns the latest stable version tag.
282	// Filters out prerelease versions.
283	func parseGitHubRelease(body []byte) (string, error) {
284		var release GitHubRelease
285		if err := json.Unmarshal(body, &release); err != nil {
286			return "", fmt.Errorf("parsing JSON: %w", err)
287		}
288	
289		if release.Prerelease {
290			return "", errors.New("only prerelease versions available")
291		}
292	
293		if release.TagName == "" {
294			return "", errors.New("empty tag name")
295		}
296	
297		return release.TagName, nil
298	}
