300	// isOutdated compares current and latest versions using semantic versioning.
301	// Returns true if current < latest.
302	func isOutdated(current, latest string) bool {
303		// Ensure versions have "v" prefix for semver package
304		if !strings.HasPrefix(current, "v") {
305			current = "v" + current
306		}
307		if !strings.HasPrefix(latest, "v") {
308			latest = "v" + latest
309		}
310	
311		// Skip notification for dev builds (e.g., "1.0.0-dev-xxx").
312		// These are local development builds and shouldn't trigger update notifications.
313		// Normal prereleases (e.g., "1.0.0-rc1") should still be compared normally.
314		if strings.Contains(semver.Prerelease(current), "dev") {
315			return false
316		}
317	
318		// semver.Compare returns -1 if current < latest
319		return semver.Compare(current, latest) < 0
320	}
321	
322	func versionCacheKey(version string) string {
323		if version == "" || strings.HasPrefix(version, "v") {
324			return version
325		}
326		return "v" + version
327	}
328	
329	func displayVersion(version string) string {
330		return strings.TrimPrefix(version, "v")
331	}
332	
333	func releaseNotesURL(version string) string {
334		return downloadsURL + "/tag/" + versionCacheKey(version)
335	}
336	
337	// executablePath is the function used to get the current executable path.
338	// It's a variable so tests can override it.
339	var executablePath = os.Executable
340	
341	func releaseChannel(version string) string {
342		if isNightly(version) {
343			return installChannelNightly
344		}
345		return installChannelStable
346	}
347	
348	func installManagerForCurrentBinary() string {
349		execPath, err := executablePath()
350		if err != nil {
351			return installManagerUnknown
352		}
353	
354		realPath, err := filepath.EvalSymlinks(execPath)
355		if err != nil {
356			realPath = execPath
357		}
358		normalizedPath := strings.ReplaceAll(filepath.ToSlash(realPath), "\\", "/")
359	
360		switch {
361		case strings.Contains(normalizedPath, "/Cellar/") ||
362			strings.Contains(normalizedPath, "/opt/homebrew/") ||
363			strings.Contains(normalizedPath, "/linuxbrew/") ||
364			strings.Contains(normalizedPath, "/Caskroom/"):
365			return installManagerBrew
366		case strings.Contains(normalizedPath, "/mise/installs/"):
367			return installManagerMise
368		case strings.Contains(normalizedPath, "/scoop/apps/"):
369			return installManagerScoop
370		default:
371			return installManagerUnknown
372		}
373	}
374	
375	// canAutoInstall reports whether updateCommand(currentVersion) is safe to
376	// execute on the current OS. Returns false on Windows when the install
377	// manager is unknown, because the POSIX curl-pipe-bash fallback can't run
378	// from cmd.exe and there's no Windows-native installer to substitute.
379	func canAutoInstall() bool {
380		if goos != goosWindows {
381			return true
382		}
383		switch installManagerForCurrentBinary() {
384		case installManagerScoop, installManagerMise:
385			return true
386		default:
387			return false
388		}
389	}
390	
391	// downloadsURL is the public page users visit when we can't offer an
392	// auto-installable command on their platform.
393	const downloadsURL = "https://github.com/entireio/cli/releases"
394	
395	// updateCommand returns the appropriate update instruction based on how the binary was installed.
396	func updateCommand(currentVersion string) string {
397		switch installManagerForCurrentBinary() {
398		case installManagerBrew:
399			if releaseChannel(currentVersion) == installChannelNightly {
400				return "brew upgrade entire@nightly"
401			}
402			return "brew upgrade entire"
403		case installManagerMise:
404			return "mise upgrade entire"
405		case installManagerScoop:
406			return "scoop update entire/cli"
407		}
408	
409		if releaseChannel(currentVersion) == installChannelNightly {
410			return "curl -fsSL https://entire.io/install.sh | bash -s -- --channel nightly"
411		}
412		return "curl -fsSL https://entire.io/install.sh | bash"
413	}
414	
415	// printNotification prints the version update notification to the user.
416	func printNotification(w io.Writer, current, latest string) {
417		fmt.Fprintf(w, "\nUpdate available! %s -> %s\nRelease notes: %s\n",
418			displayVersion(current), displayVersion(latest), releaseNotesURL(latest))
419	}
