12	// autoUpdateFixture wires the test seams for MaybeAutoUpdate.
13	type autoUpdateFixture struct {
14		installCalls int
15		installErr   error
16		lastCommand  string
17		confirmValue bool
18		confirmErr   error
19		chooseValue  AutoUpdateAction
20		chooseErr    error
21	}
