23	func newAutoUpdateFixture(t *testing.T) *autoUpdateFixture {
24		t.Helper()
25		t.Setenv("HOME", t.TempDir())
26		t.Setenv(envKillSwitch, "")
27		// Force interactive mode on by default; individual tests can opt out.
28		t.Setenv("ENTIRE_TEST_TTY", "1")
29	
30		f := &autoUpdateFixture{confirmValue: true, chooseValue: autoUpdateActionUpdate}
31	
32		origRun := runInstaller
33		runInstaller = func(_ context.Context, cmd string) error {
34			f.installCalls++
35			f.lastCommand = cmd
36			return f.installErr
37		}
38		origConfirm := confirmUpdate
39		confirmUpdate = func() (bool, error) { return f.confirmValue, f.confirmErr }
40		origChoose := chooseBrewUpdate
41		chooseBrewUpdate = func(io.Writer) (AutoUpdateAction, error) { return f.chooseValue, f.chooseErr }
42		origIsTerminalOut := isTerminalOut
43		isTerminalOut = func(_ io.Writer) bool { return true }
44	
45		t.Cleanup(func() {
46			runInstaller = origRun
47			confirmUpdate = origConfirm
48			chooseBrewUpdate = origChoose
49			isTerminalOut = origIsTerminalOut
50		})
51		return f
52	}
