64	// assertManualHint checks that the "To update entire run:\n  <cmd>" hint
65	// was printed when the prompt couldn't be shown.
66	func assertManualHint(t *testing.T, out string) {
67		t.Helper()
68		if !strings.Contains(out, "To update, run:") {
69			t.Errorf("missing manual-update hint: %q", out)
70		}
71		if !strings.Contains(out, "brew upgrade entire") {
72			t.Errorf("manual hint missing installer command: %q", out)
73		}
74		if strings.Contains(out, "1. Update now") ||
75			strings.Contains(out, "2. Skip") ||
76			strings.Contains(out, "3. Skip until next version") ||
77			strings.Contains(out, "Press enter to continue") {
78			t.Errorf("non-interactive output included interactive menu: %q", out)
79		}
80	}
