141	// TestMaybeAutoUpdate_WindowsUnknownInstallerNoAutoRun verifies that on
142	// Windows without a detected install manager we never execute the POSIX
143	// curl-pipe-bash fallback (which would error from cmd.exe). Instead the
144	// user is pointed at the releases download page.
145	func TestMaybeAutoUpdate_WindowsUnknownInstallerNoAutoRun(t *testing.T) {
146		f := newAutoUpdateFixture(t)
147		// Force unknown install manager: point executablePath at a plain
148		// Program Files path that matches none of the known prefixes.
149		orig := executablePath
150		executablePath = func() (string, error) {
151			return `C:\Program Files\Entire\entire.exe`, nil
152		}
153		t.Cleanup(func() { executablePath = orig })
154	
155		origGOOS := goos
156		goos = goosWindows
