20	func TestIsOutdated(t *testing.T) {
21		tests := []struct {
22			current string
23			latest  string
24			want    bool
25			desc    string
26		}{
27			// Standard semver cases
28			{"1.0.0", "1.0.1", true, "patch version bump"},
29			{"1.0.0", "1.1.0", true, "minor version bump"},
30			{"1.0.0", "2.0.0", true, "major version bump"},
31			{"1.0.1", "1.0.0", false, "current is newer"},
32			{"2.0.0", "1.9.9", false, "current major is higher"},
33			{"1.0.0", "1.0.0", false, "same version"},
34	
35			// v-prefix handling
36			{"v1.0.0", "v1.0.1", true, "with v prefix"},
37			{"v1.0.0", "1.0.1", true, "mixed v prefix"},
38			{"1.0.0", "v1.0.1", true, "mixed v prefix reversed"},
39	
40			// Pre-release versions (semver uses hyphen)
41			{"1.0.0-rc1", "1.0.0", true, "prerelease in current"},
42			{"1.0.0", "1.0.1-rc1", true, "prerelease in latest is still newer"},
43			{"1.0.0-dev-xxx", "1.0.1", false, "dev build skips version check"},
44	
45			// Nightly-vs-nightly comparisons (same channel)
46			{"0.5.3-nightly.202604051159.abc1234", "0.5.3-nightly.202604061200.def5678", true, "older nightly is outdated by newer nightly"},
47			{"0.5.3-nightly.202604061200.def5678", "0.5.3-nightly.202604051159.abc1234", false, "newer nightly is not outdated by older nightly"},
48			{"0.5.3-nightly.202604061200.abc1234", "0.5.3-nightly.202604061200.abc1234", false, "same nightly is not outdated"},
49		}
50	
51		for _, tt := range tests {
52			t.Run(tt.desc, func(t *testing.T) {
53				got := isOutdated(tt.current, tt.latest)
54				if got != tt.want {
55					t.Errorf("isOutdated(%q, %q) = %v, want %v", tt.current, tt.latest, got, tt.want)
56				}
57			})
58		}
59	}
