132	func TestCacheReadWrite(t *testing.T) {
133		// Create a temporary directory for the test
134		tmpDir := t.TempDir()
135	
136		// Create config directory structure
137		configDir := filepath.Join(tmpDir, globalConfigDirName)
138		if err := os.MkdirAll(configDir, 0o755); err != nil {
139			t.Fatalf("Failed to create config dir: %v", err)
140		}
141	
142		// Test saving and loading cache directly to temp directory
143		originalCache := &VersionCache{
144			LastCheckTime: time.Now().Round(time.Second), // Round to second for JSON consistency
145		}
146	
147		// Write cache manually to temp directory
148		filePath := filepath.Join(configDir, cacheFileName)
149		data, err := json.MarshalIndent(originalCache, "", "  ")
150		if err != nil {
151			t.Fatalf("json.MarshalIndent() error = %v", err)
152		}
153	
154		if err := os.WriteFile(filePath, data, 0o644); err != nil {
155			t.Fatalf("WriteFile() error = %v", err)
156		}
157	
158		// Load and verify
159	
160		loadedData, err := os.ReadFile(filePath)
161		if err != nil {
162			t.Fatalf("ReadFile() error = %v", err)
163		}
164	
165		var loaded VersionCache
166		if err := json.Unmarshal(loadedData, &loaded); err != nil {
167			t.Fatalf("json.Unmarshal() error = %v", err)
168		}
169	
170		// Verify the loaded cache LastCheckTime matches (within 1 second tolerance for JSON rounding)
171		if loaded.LastCheckTime.Sub(originalCache.LastCheckTime).Abs() > time.Second {
172			t.Errorf("LastCheckTime = %v, want %v", loaded.LastCheckTime, originalCache.LastCheckTime)
173		}
174	
175		// Verify file exists
176		if _, err := os.Stat(filePath); err != nil {
177			t.Errorf("cache file not found at %s: %v", filePath, err)
178		}
179	}
